-- Adhunik ERP — Phase 10B Monthly Payroll
begin;
insert into public.erp_permission_sections(module_key,section_key,module_name,section_name,sort_order)values
('hr-payroll','hr-payroll.monthly_payroll','HR & Payroll','Monthly Payroll',925),('hr-payroll','hr-payroll.payroll_history','HR & Payroll','Payroll History',927)
on conflict(section_key)do update set module_name=excluded.module_name,section_name=excluded.section_name,sort_order=excluded.sort_order,is_active=true;
create table public.payroll_runs(id uuid primary key default gen_random_uuid(),month smallint not null check(month between 1 and 12),year smallint not null check(year between 2000 and 2200),status text not null default'DRAFT'check(status in('DRAFT','FINALIZED')),prepared_by uuid not null references auth.users(id)default auth.uid(),prepared_at timestamptz not null default now(),finalized_by uuid references auth.users(id),finalized_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(month,year),check(status<>'FINALIZED'or(finalized_by is not null and finalized_at is not null)));
create table public.employee_monthly_payroll(id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.payroll_runs(id)on delete restrict,employee_id uuid not null references public.employees(id)on delete restrict,salary_structure_id uuid references public.employee_salary_structures(id)on delete restrict,attendance_id uuid references public.monthly_attendance(id)on delete restrict,status text not null default'DRAFT'check(status in('DRAFT','FINALIZED')),eligibility_error text,employee_code text not null,employee_name text not null,department text,designation text,basic numeric(15,2)not null default 0,hra numeric(15,2)not null default 0,allowance numeric(15,2)not null default 0,other_earnings numeric(15,2)not null default 0,fixed_gross numeric(15,2)not null default 0,working_days numeric(6,2)not null default 0,present_days numeric(6,2)not null default 0,weekly_offs numeric(6,2)not null default 0,absent_days numeric(6,2)not null default 0,total_payable_days numeric(6,2)not null default 0,paid_days numeric(6,2)not null default 0,payable_basic numeric(15,2)not null default 0,payable_hra numeric(15,2)not null default 0,payable_allowance numeric(15,2)not null default 0,payable_other_earnings numeric(15,2)not null default 0,attendance_salary numeric(15,2)not null default 0,crm_eligible_amount numeric(15,2)not null default 0,crm_incentive_percentage numeric(7,4)not null default 0 check(crm_incentive_percentage>=0),crm_incentive_amount numeric(15,2)not null default 0,overtime_amount numeric(15,2)not null default 0 check(overtime_amount>=0),adjustment_amount numeric(15,2)not null default 0,adjustment_reason text,net_payable numeric(15,2)not null default 0,created_by uuid not null references auth.users(id)default auth.uid(),updated_by uuid references auth.users(id)default auth.uid(),finalized_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),finalized_at timestamptz,unique(payroll_run_id,employee_id),check(adjustment_amount=0 or nullif(trim(adjustment_reason),'')is not null));
create table public.payroll_crm_incentive_details(id uuid primary key default gen_random_uuid(),payroll_id uuid not null references public.employee_monthly_payroll(id)on delete restrict,proforma_invoice_id uuid references public.proforma_invoices(id)on delete restrict,pi_number text not null,pi_date date not null,customer text not null,eligible_amount numeric(15,2)not null check(eligible_amount>=0),created_at timestamptz not null default now(),unique(payroll_id,proforma_invoice_id));
create table public.payroll_audit(id uuid primary key default gen_random_uuid(),payroll_run_id uuid references public.payroll_runs(id),payroll_id uuid references public.employee_monthly_payroll(id),event_type text not null,old_value jsonb,new_value jsonb,reason text,changed_by uuid not null references auth.users(id)default auth.uid(),changed_at timestamptz not null default now());
create index payroll_runs_period on public.payroll_runs(year desc,month desc);create index employee_payroll_history on public.employee_monthly_payroll(employee_id,finalized_at desc);create index payroll_details_payroll on public.payroll_crm_incentive_details(payroll_id);
create or replace function public.prepare_payroll(p_month smallint,p_year smallint)returns uuid language plpgsql security definer set search_path=''as $$declare r uuid;e record;s record;a record;p uuid;ratio numeric;eligible numeric;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;insert into public.payroll_runs(month,year)values(p_month,p_year)on conflict(month,year)do update set updated_at=now()where public.payroll_runs.status='DRAFT'returning id into r;if r is null then raise exception'Payroll is already finalized';end if;for e in select x.*,d.name department,g.name designation from public.employees x left join public.departments d on d.id=x.department_id left join public.designations g on g.id=x.designation_id where x.is_active and x.deleted_at is null loop select * into s from public.employee_salary_structures where employee_id=e.id and effective_from<=make_date(p_year,p_month,1)order by effective_from desc limit 1;select * into a from public.monthly_attendance where employee_id=e.id and month=p_month and year=p_year;ratio:=case when a.total_payable_days>0 then a.paid_days/a.total_payable_days else 0 end;select coalesce(sum(pi.subtotal),0)into eligible from public.proforma_invoices pi join public.erp_profiles ep on ep.auth_user_id=pi.salesperson_id where ep.employee_id=e.id and pi.status in('ISSUED','ACCEPTED')and extract(month from pi.pi_date)=p_month and extract(year from pi.pi_date)=p_year;insert into public.employee_monthly_payroll(payroll_run_id,employee_id,salary_structure_id,attendance_id,eligibility_error,employee_code,employee_name,department,designation,basic,hra,allowance,other_earnings,fixed_gross,working_days,present_days,weekly_offs,absent_days,total_payable_days,paid_days,payable_basic,payable_hra,payable_allowance,payable_other_earnings,attendance_salary,crm_eligible_amount,net_payable)values(r,e.id,s.id,a.id,case when s.id is null then'Missing Salary Structure'when a.id is null then'Missing Attendance'when a.total_payable_days<=0 then'Invalid Total Payable Days'end,e.employee_code,e.full_name,e.department,e.designation,coalesce(s.basic,0),coalesce(s.hra,0),coalesce(s.allowance,0),coalesce(s.other_earnings,0),coalesce(s.fixed_gross,0),coalesce(a.working_days,0),coalesce(a.present_days,0),coalesce(a.weekly_offs,0),coalesce(a.absent_days,0),coalesce(a.total_payable_days,0),coalesce(a.paid_days,0),round(coalesce(s.basic,0)*ratio,2),round(coalesce(s.hra,0)*ratio,2),round(coalesce(s.allowance,0)*ratio,2),round(coalesce(s.other_earnings,0)*ratio,2),round(coalesce(s.fixed_gross,0)*ratio,2),eligible,round(coalesce(s.fixed_gross,0)*ratio,2))on conflict(payroll_run_id,employee_id)do update set salary_structure_id=excluded.salary_structure_id,attendance_id=excluded.attendance_id,eligibility_error=excluded.eligibility_error,employee_code=excluded.employee_code,employee_name=excluded.employee_name,department=excluded.department,designation=excluded.designation,basic=excluded.basic,hra=excluded.hra,allowance=excluded.allowance,other_earnings=excluded.other_earnings,fixed_gross=excluded.fixed_gross,working_days=excluded.working_days,present_days=excluded.present_days,weekly_offs=excluded.weekly_offs,absent_days=excluded.absent_days,total_payable_days=excluded.total_payable_days,paid_days=excluded.paid_days,payable_basic=excluded.payable_basic,payable_hra=excluded.payable_hra,payable_allowance=excluded.payable_allowance,payable_other_earnings=excluded.payable_other_earnings,attendance_salary=excluded.attendance_salary,crm_eligible_amount=excluded.crm_eligible_amount,crm_incentive_amount=round(excluded.crm_eligible_amount*public.employee_monthly_payroll.crm_incentive_percentage/100,2),net_payable=round(excluded.attendance_salary+excluded.crm_eligible_amount*public.employee_monthly_payroll.crm_incentive_percentage/100+public.employee_monthly_payroll.overtime_amount+public.employee_monthly_payroll.adjustment_amount,2),updated_at=now()returning id into p;delete from public.payroll_crm_incentive_details where payroll_id=p;insert into public.payroll_crm_incentive_details(payroll_id,proforma_invoice_id,pi_number,pi_date,customer,eligible_amount)select p,pi.id,pi.pi_number,pi.pi_date,pi.customer_name_snapshot,pi.subtotal from public.proforma_invoices pi join public.erp_profiles ep on ep.auth_user_id=pi.salesperson_id where ep.employee_id=e.id and pi.status in('ISSUED','ACCEPTED')and extract(month from pi.pi_date)=p_month and extract(year from pi.pi_date)=p_year;end loop;insert into public.payroll_audit(payroll_run_id,event_type)values(r,'PAYROLL_PREPARED');return r;end$$;
create or replace function public.update_payroll_variables(p_id uuid,p_percentage numeric,p_overtime numeric,p_adjustment numeric,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare x public.employee_monthly_payroll%rowtype;begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;select * into x from public.employee_monthly_payroll where id=p_id and status='DRAFT'for update;if not found then raise exception'Draft payroll not found';end if;if p_percentage<0 or p_overtime<0 or(p_adjustment<>0 and nullif(trim(p_reason),'')is null)then raise exception'Invalid payroll variables or missing adjustment reason';end if;update public.employee_monthly_payroll set crm_incentive_percentage=p_percentage,crm_incentive_amount=round(crm_eligible_amount*p_percentage/100,2),overtime_amount=p_overtime,adjustment_amount=p_adjustment,adjustment_reason=nullif(trim(p_reason),''),net_payable=round(attendance_salary+crm_eligible_amount*p_percentage/100+p_overtime+p_adjustment,2),updated_by=auth.uid(),updated_at=now()where id=p_id;insert into public.payroll_audit(payroll_run_id,payroll_id,event_type,old_value,new_value,reason)values(x.payroll_run_id,p_id,'PAYROLL_UPDATED',jsonb_build_object('percentage',x.crm_incentive_percentage,'overtime',x.overtime_amount,'adjustment',x.adjustment_amount),jsonb_build_object('percentage',p_percentage,'overtime',p_overtime,'adjustment',p_adjustment),p_reason);end$$;
create or replace function public.finalize_payroll(p_run uuid)returns void language plpgsql security definer set search_path=''as $$begin if not public.has_erp_permission('hr-payroll.monthly_payroll','EDIT')then raise exception'Monthly Payroll edit permission required';end if;perform 1 from public.payroll_runs where id=p_run and status='DRAFT'for update;if not found then raise exception'Draft payroll not found';end if;if exists(select 1 from public.employee_monthly_payroll where payroll_run_id=p_run and eligibility_error is not null)then raise exception'Resolve all payroll eligibility errors';end if;if exists(select 1 from public.employee_monthly_payroll where payroll_run_id=p_run and adjustment_amount<>0 and nullif(trim(adjustment_reason),'')is null)then raise exception'Adjustment reason required';end if;update public.employee_monthly_payroll set status='FINALIZED',finalized_by=auth.uid(),finalized_at=now(),updated_by=auth.uid(),updated_at=now()where payroll_run_id=p_run;update public.payroll_runs set status='FINALIZED',finalized_by=auth.uid(),finalized_at=now(),updated_at=now()where id=p_run;insert into public.payroll_audit(payroll_run_id,event_type)values(p_run,'PAYROLL_FINALIZED');end$$;
create or replace function public.my_employee_id()returns uuid language sql stable security definer set search_path=''as $$select employee_id from public.erp_profiles where auth_user_id=auth.uid()and is_active limit 1$$;
create or replace function public.lock_finalized_payroll()returns trigger language plpgsql as $$begin if old.status='FINALIZED'then raise exception'Finalized payroll is locked';end if;return new;end$$;create trigger lock_employee_payroll before update on public.employee_monthly_payroll for each row execute function public.lock_finalized_payroll();
alter table public.payroll_runs enable row level security;alter table public.employee_monthly_payroll enable row level security;alter table public.payroll_crm_incentive_details enable row level security;alter table public.payroll_audit enable row level security;
create policy payroll_runs_hr_read on public.payroll_runs for select to authenticated using(public.has_erp_permission('hr-payroll.monthly_payroll','VIEW')or public.has_erp_permission('hr-payroll.payroll_history','VIEW'));
create policy employee_payroll_read on public.employee_monthly_payroll for select to authenticated using(public.has_erp_permission(case when status='FINALIZED'then'hr-payroll.payroll_history'else'hr-payroll.monthly_payroll'end,'VIEW')or(status='FINALIZED'and employee_id=public.my_employee_id()));
create policy payroll_crm_read on public.payroll_crm_incentive_details for select to authenticated using(exists(select 1 from public.employee_monthly_payroll p where p.id=payroll_id and(public.has_erp_permission('hr-payroll.monthly_payroll','VIEW')or public.has_erp_permission('hr-payroll.payroll_history','VIEW'))));
create policy payroll_audit_hr_read on public.payroll_audit for select to authenticated using(public.has_erp_permission('hr-payroll.monthly_payroll','VIEW'));
grant select on public.payroll_runs,public.employee_monthly_payroll,public.payroll_crm_incentive_details,public.payroll_audit to authenticated;revoke all on function public.prepare_payroll(smallint,smallint),public.update_payroll_variables(uuid,numeric,numeric,numeric,text),public.finalize_payroll(uuid)from public,anon;grant execute on function public.prepare_payroll(smallint,smallint),public.update_payroll_variables(uuid,numeric,numeric,numeric,text),public.finalize_payroll(uuid)to authenticated;
insert into public.erp_user_permissions(profile_id,section_id,can_view,can_edit,created_by,updated_by)select p.id,s.id,true,true,p.auth_user_id,p.auth_user_id from public.erp_profiles p join public.erp_roles r on r.id=p.role_id cross join public.erp_permission_sections s where r.code='MANAGER'and s.section_key in('hr-payroll.monthly_payroll','hr-payroll.payroll_history')on conflict(profile_id,section_id)do nothing;
commit;
